<?php declare(strict_types=1);require dirname(__DIR__).'/_bootstrap.php';require_post();$user=api_user();api_rate_limit($user,'hunts.activation',10,60);$data=json_input();$huntId=(int)($data['hunt_id']??0);$paymentId=(int)($data['payment_transaction_id']??0);try{$result=activate_hunt_for_user((int)$user['id'],$huntId,'ONLINE',$paymentId,null);json_response(true,'Hunt activation is active',$result,$result['created']?201:200);}catch(InvalidArgumentException $e){json_response(false,$e->getMessage(),null,422);}catch(RuntimeException $e){json_response(false,$e->getMessage(),null,409);}
